fn solve_cookie_distribution(a: u8, b: u8, n: u8, m: u8) -> bool {
    // Each special guest consumes one cookie from each pile,
    // so each pile must have at least `m` cookies.
    if a < m || b < m {
        return false;
    }

    // After allocating m cookies from each pile to the special guests,
    // see if the remaining cookies across both piles can cover the n regular guests.
    let remaining = (a - m) as u16 + (b - m) as u16;
    remaining >= n as u16
}

